def parse_amount(value: str) -> float:
    try:
        return float(value)
    except ValueError as exc:
        raise ValueError(f"amount inválido: {value!r}") from exc

parse_amount("12.50")

def normalize_amount(value: int | float) -> float:
    return float(value)

result: float = normalize_amount(10)
print(result)

def normalize_status(value: str) -> str:
    return value.strip().lower()

def test_normalize_status() -> None:
    assert normalize_status(" PAID ") == "paid"

